import numpy as np
import matplotlib.pyplot as plt

# Load saved test data
x_test = np.load("../datasets/x_test_0.npy")
y_test = np.load("../datasets/y_test_0.npy")

# Load predictions generated by the analysis script
predictions = np.load("results/cnn_1/predictions.npy")

# Calculate errors
errors = predictions - y_test
absolute_errors = np.abs(errors)

fig, axes = plt.subplots(1, 3, figsize=(18, 5))

# 1. Actual vs predicted
axes[0].scatter(y_test, predictions, alpha=0.5)
axes[0].plot(
    [y_test.min(), y_test.max()],
    [y_test.min(), y_test.max()],
    linestyle="--"
)
axes[0].set_title("Actual vs Predicted")
axes[0].set_xlabel("Actual Einstein radius (arcsec)")
axes[0].set_ylabel("Predicted Einstein radius (arcsec)")
axes[0].grid(True, alpha=0.3)

# 2. Absolute error distribution
axes[1].hist(absolute_errors, bins=30)
axes[1].set_title("Absolute Error Distribution")
axes[1].set_xlabel("Absolute error (arcsec)")
axes[1].set_ylabel("Number of samples")
axes[1].grid(True, alpha=0.3)

# 3. Error vs true Einstein radius
axes[2].scatter(y_test, errors, alpha=0.5)
axes[2].axhline(0, linestyle="--")
axes[2].set_title("Prediction Error vs Actual Einstein Radius")
axes[2].set_xlabel("Actual Einstein radius (arcsec)")
axes[2].set_ylabel("Prediction error (arcsec)")
axes[2].grid(True, alpha=0.3)

plt.tight_layout()

plt.savefig(
    "results/cnn_1/test_error_analysis.png",
    dpi=180,
    bbox_inches="tight"
)

plt.show()